using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    public void register_commands(Control o)
    {
        var commands=new Settings();void Add(string name,Action action)=>commands[name]=Callable.From(action);foreach(var entry in new[]{("Play / Pause","toggle_playback"),("Stop","stop"),("Import Audio","import_audio"),("Save Composition","save"),("Collect Portable Copy","review_portable_copy"),("Open Collected Copy","open_collected_copy"),("Export Audio","export_dialog"),("Review Recovery","review_recovery"),("Undo","undo"),("Redo","redo"),("Add Track","add_track_dialog"),("New Instrument Pattern","new_pattern"),("Project Conductor","conductor_dialog"),("Uniformly Retime Notes","retime_notes_dialog"),("Generate Music","music_dialog"),("Arrangement Sections","arrangement_dialog"),("Harmonize Melody","harmonize_notes"),("Render Exact Preview","render_preview"),("Render In Place","render_in_place"),("Join Selected Clips","render_in_place"),("Batch Apply Effects","batch_effects"),("Bounce Track","bounce_track"),("Freeze Track","freeze_track"),("Unfreeze Track","unfreeze_track"),("Loop Selection","loop_selection"),("Fit Timeline","fit_timeline"),("Add Marker","add_marker"),("Add Effect","add_effect_dialog"),("Effect Chain Presets","effect_chain_dialog"),("Analyze Clip","analyze_clip"),("Learn Noise Profile","sample_noise_profile"),("Align Selected Clips","align_selected"),("Match RMS Levels","match_levels"),("Dialogue Ducking","ducking_dialog"),("Record Automation","automation_record_target_dialog"),("Automation","automation_dialog"),("Sends","send_dialog"),("Relink Source","relink_source"),("Record","toggle_recording"),("Recording Options","recording_options"),("Recording Takes","take_dialog"),("Import MIDI","import_midi"),("Export MIDI","export_midi"),("Export Timeline Notes MIDI","export_timeline_midi"),("Save Selected Layer Bundle","save_layer_bundle"),("Import Native Preset","import_native_preset"),("Recover Presets","preset_recovery_dialog"),("Review Selected Dialogue","review_dialogue_batch"),("Modulation Matrix","modulation_matrix_dialog"),("Fit Selected Notes to Conductor","fit_notes_to_conductor_dialog"),("Customize Shortcuts","customize_shortcuts"),("Provider Status","provider_status")}){string method=entry.Item2;Add(entry.Item1,()=>o.Call(method));}Add("Checkpoint Now",()=>queue_recovery_checkpoint(o,true));Add("Copy Clips",()=>Session(o).Call("copy"));Add("Paste Clips",()=>Session(o).Call("paste",Position(o),Session(o).Get("selected_track")));Add("Duplicate Clips",()=>Session(o).Call("duplicate_selected"));Add("Delete Clips",()=>Session(o).Call("delete_selected"));Add("Ripple Delete",()=>Session(o).Call("delete_selected",true));Add("Split At Playhead",()=>Session(o).Call("split_selected",Position(o)));Add("Crossfade Clips",()=>Session(o).Call("crossfade_selected"));Add("New Drum Pattern",()=>new_pattern(o,true));Add("Save Composition Preset",()=>save_preset(o,"composition"));foreach(var entry in new[]{("Transcribe Selected Clip Locally","transcribe"),("Review Saved Transcript","review_saved_transcript"),("Generate Cloud Speech (Opt-in)","speech"),("Optional Speech Tool Setup","configure")}){string method=entry.Item2;Add(entry.Item1,()=>Field<Node>(o,"_optional_tools").Call(method));}o.Set("_commands",commands);long ctrl=(long)KeyModifierMask.MaskCtrl,shift=(long)KeyModifierMask.MaskShift;var shortcuts=new Settings{["Play / Pause"]=(long)Key.Space,["Stop"]=(long)Key.Home,["Save Composition"]=ctrl|(long)Key.S,["Undo"]=ctrl|(long)Key.Z,["Redo"]=ctrl|shift|(long)Key.Z,["Copy Clips"]=ctrl|(long)Key.C,["Paste Clips"]=ctrl|(long)Key.V,["Duplicate Clips"]=ctrl|(long)Key.D,["Delete Clips"]=(long)Key.Delete,["Split At Playhead"]=(long)Key.S,["Record"]=(long)Key.R,["Loop Selection"]=(long)Key.L,["Fit Timeline"]=(long)Key.F};o.Set("_shortcuts",shortcuts);
