    public void run_command(Control o,string name){var commands=Dict(o,"_commands");if(!commands.ContainsKey(name))return;if(name!="Customize Shortcuts")o.Set("_last_command",name);o.Call("_invoke_action",commands[name]);}
    public void command_palette(Control o)
    {
        var dialog=window(o,"Audio Commands",new Vector2I(540,480));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();var search=new LineEdit{PlaceholderText="Search actions…"};host.AddChild(search);var list=new ItemList{SizeFlagsVertical=Control.SizeFlags.ExpandFill};host.AddChild(list);void Refresh(string query){list.Clear();foreach(var key in Dict(o,"_commands").Keys){string name=key.AsString();if(query.Length>0&&!name.ToLowerInvariant().Contains(query.ToLowerInvariant()))continue;long shortcut=Get(Dict(o,"_shortcuts"),name,0).AsInt64();int index=list.AddItem(name+(shortcut!=0?"   "+OS.GetKeycodeString((Key)shortcut):""));list.SetItemMetadata(index,name);}}search.TextChanged+=Refresh;Refresh("");list.ItemActivated+=index=>{string action=list.GetItemMetadata((int)index).AsString();windowNode.QueueFree();run_command(o,action);};search.TextSubmitted+=_=>{if(list.ItemCount==0)return;string action=list.GetItemMetadata(0).AsString();windowNode.QueueFree();run_command(o,action);};search.GrabFocus();
    }
    public void customize_shortcuts(Control o)
    {
        var dialog=window(o,"Keyboard Shortcuts",new Vector2I(550,500));var host=dialog["host"].As<Node>();label(host,"Choose an action, then press its shortcut. Text fields keep normal typing shortcuts. Escape cancels capture.");var list=new ItemList{SizeFlagsVertical=Control.SizeFlags.ExpandFill};host.AddChild(list);foreach(var raw in Dict(o,"_commands").Keys){string name=raw.AsString();int index=list.AddItem(name+"   "+OS.GetKeycodeString((Key)Get(Dict(o,"_shortcuts"),name,0).AsInt64()));list.SetItemMetadata(index,name);}string action="";list.ItemActivated+=index=>{action=list.GetItemMetadata((int)index).AsString();Field<Label>(o,"status").Text="Press a shortcut for "+action;};list.GuiInput+=input=>{if(input is not InputEventKey key||!key.Pressed||key.Echo||action.Length==0)return;list.AcceptEvent();if(key.Keycode==Key.Escape){action="";return;}long code=(long)key.GetKeycodeWithModifiers();var shortcuts=Dict(o,"_shortcuts");var remove=new GArray();foreach(var name in shortcuts.Keys)if(shortcuts[name].AsInt64()==code)remove.Add(name);foreach(var name in remove)shortcuts.Remove(name);shortcuts[action]=code;action="";using var config=new ConfigFile();config.SetValue("keys","commands",shortcuts);DirAccess.MakeDirRecursiveAbsolute(ProjectSettings.GlobalizePath("user://audio_workspace"));config.Save("user://audio_workspace/shortcuts.cfg");for(int index=0;index<list.ItemCount;index++){string name=list.GetItemMetadata(index).AsString();list.SetItemText(index,name+"   "+OS.GetKeycodeString((Key)Get(shortcuts,name,0).AsInt64()));}};
    }
    public void unhandled_key_input(Control o,InputEvent input)
    {
        if(!o.IsVisibleInTree()||input is not InputEventKey key||!key.Pressed||key.Echo)return;var viewport=o.GetViewport();var focused=viewport.GuiGetFocusOwner();if(focused is LineEdit or TextEdit)return;long code=(long)key.GetKeycodeWithModifiers();if(code==((long)KeyModifierMask.MaskCtrl|(long)Key.K)){command_palette(o);viewport.SetInputAsHandled();return;}if(code==((long)KeyModifierMask.MaskCtrl|(long)KeyModifierMask.MaskShift|(long)Key.R)&&o.Get("_last_command").AsString().Length>0){run_command(o,o.Get("_last_command").AsString());viewport.SetInputAsHandled();return;}var shortcuts=Dict(o,"_shortcuts");foreach(var name in shortcuts.Keys)if(shortcuts[name].AsInt64()==code){run_command(o,name.AsString());viewport.SetInputAsHandled();return;}
    }
}
